def get_viloyatlar():
    """Barcha viloyatlar ro'yxati"""
    return sorted(set(p["viloyat"] for p in BTC_POINTS))


def get_tumanlar(viloyat: str):
    """Berilgan viloyatdagi barcha tumanlar"""
    return sorted(set(p["tuman"] for p in BTC_POINTS if p["viloyat"] == viloyat))


def get_btc_points(viloyat: str, tuman: str):
    """Berilgan viloyat va tumandagi barcha BTC punktlar"""
    return [p for p in BTC_POINTS if p["viloyat"] == viloyat and p["tuman"] == tuman]


def get_point_by_kod(kod: int):
    """Kod bo'yicha bitta punktni topish"""
    for p in BTC_POINTS:
        if p["kod"] == kod:
            return p
    return None


def get_nearest_points(lat: float, lon: float, limit: int = 3):
    """User lokatsiyasiga eng yaqin punktlarni qaytaradi (Haversine formulasi)"""
    from math import radians, sin, cos, sqrt, atan2
    
    def distance(lat1, lon1, lat2, lon2):
        R = 6371  # Yer radiusi km
        lat1, lon1, lat2, lon2 = map(radians, [lat1, lon1, lat2, lon2])
        dlat = lat2 - lat1
        dlon = lon2 - lon1
        a = sin(dlat/2)**2 + cos(lat1) * cos(lat2) * sin(dlon/2)**2
        c = 2 * atan2(sqrt(a), sqrt(1-a))
        return R * c
    
    points_with_dist = []
    for p in BTC_POINTS:
        if p["lat"] and p["lon"]:
            dist = distance(lat, lon, p["lat"], p["lon"])
            points_with_dist.append((dist, p))
    
    points_with_dist.sort(key=lambda x: x[0])
    return [(round(d, 2), p) for d, p in points_with_dist[:limit]]
